// 登记是通知来源，死亡原因才是在世资格边界；同tick也按原Common顺序，不改旧登记读口。
#include "resident/domains/family/actor_life_eligibility.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool b,const char* s){++checks;if(!b)throw std::runtime_error(s);}}
int main(){try{
    auto cat=std::make_shared<CommonCatalog>();CommonState seed;seed.identity.tick=3;seed.identity.world_id[0]=1;seed.metadata.scenario_id="scenario";ActorRecord person;person.id="actor";person.alive=false;seed.actors.insert(person.id,person);seed.facts.insert("before",{"before","legal","test"});seed.facts.insert("cause",{"cause","military_casualties","military"});seed.facts.insert("between",{"between","legal","test"});seed.facts.insert("death",{"death","family_death","family_life"});seed.facts.insert("after",{"after","legal","test"});CommonStore common(seed,cat);FamilyDeathState life;FamilyDeathRecord death;death.actor_id="actor";death.scenario_id="scenario";death.world_id=seed.identity.world_id;death.cause_fact_id="cause";death.battle_id="battle";death.death_tick=2;death.recorded_tick=2;life.deaths.insert("death",death);
    auto a=read_actor_alive_before_fact(common,life,"actor",2,"before");check(a.ok&&a.value,"earlier same tick signature stays living");a=read_actor_alive_before_fact(common,life,"actor",2,"between");check(a.ok&&!a.value,"cause before registration is already dead");auto registered=read_actor_death_before_fact(common,life,"actor",2,"between");check(registered.ok&&!registered.value,"old registered-notice semantics unchanged");a=read_actor_alive_before_fact(common,life,"actor",2,"after");check(a.ok&&!a.value,"after registration dead");check(!read_actor_alive_before_fact(common,life,"actor",1,"between").ok,"source order contradicts claimed tick");check(!read_actor_alive_before_fact(common,life,"actor",3,"before").ok,"later claimed tick cannot precede death source");check(!read_actor_alive_before_fact(common,life,"actor",4,"after").ok,"future not accepted");check(!read_actor_alive_before_fact(common,life,"actor",2,"missing").ok,"missing exact boundary");life.deaths.erase("death");check(!read_actor_alive_before_fact(common,life,"actor",2,"before").ok,"current dead with unknown source rejected");common.state().facts.erase("death");common.state().facts.erase("cause");common.state().actors.find("actor")->alive=true;a=read_actor_alive_before_fact(common,life,"actor",2,"before");check(a.ok&&a.value,"validated living actor remains living");std::cout<<"ACTOR_ALIVE_HISTORY "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<"ACTOR_ALIVE_HISTORY "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
